import{z as l,x as M,o as E,c as n,q as r,j as T,D as A,d as e,s as B,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"SMTP / IMAP","description":"","frontmatter":{"title":"SMTP / IMAP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/smtp-imap.md","filePath":"cs/smtp-imap.md","lastUpdated":1791413859000}'),o={name:"cs/smtp-imap.md"};function p(P,a,d,m,S,D){const t=M("Mermaid");return E(),n("div",null,[a[2]||(a[2]=r('<h1 id="smtp-imap" tabindex="-1">SMTP / IMAP <a class="header-anchor" href="#smtp-imap" aria-label="Permalink to &quot;SMTP / IMAP&quot;">​</a></h1><div class="epigraph"><p>SMTP 在 MTA 之间推送邮件；IMAP 让客户端在服务器上管理邮箱。提交与投递端口、TLS 时机不同，都不是 HTTP。</p><footer>—— 据 RFC 5321 SMTP；RFC 9051 IMAP4rev2 整理</footer></div><p><a href="/cs/geodns">上一课</a> 不传邮箱。<a href="/cs/dns-rr">DNS MX</a> 已点名记录。缺口是<strong>邮件运输与存取</strong>：SMTP 对话、IMAP 选文件夹。本课不把 SPF 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>邮件要跨管理域、要存、要多设备。SMTP：MAIL FROM、RCPT TO、DATA，MTA 跳到跳，MX 决定下一跳。提交（587）与传输（25）政策不同。IMAP：TCP 上命令取消息，状态在服务器；POP 对照为下载删除，点名。持久连接、大附件 MTU、超时与无线半开都出现。不是 REST 资源模型。</p><p>不要把 Gmail 网页当协议。</p><p><span class="marginnote">术语翻译：MUA（Mail User Agent）是你手上的邮件客户端，MTA（Mail Transfer Agent）是服务器之间的搬运工。信从 MUA 交给 MTA 只走一次提交，之后 MTA 到 MTA 像接力赛，每一跳只查「下一个收件域的 MX 记录在哪」，并不关心这封信最终落在谁的收件箱里。</span></p><p><span class="marginnote">RFC 5321。STARTTLS 升级。本课不把每条 SMTP 代码背完。</span></p><h3 id="投递链与邮箱存取" tabindex="-1">投递链与邮箱存取 <a class="header-anchor" href="#投递链与邮箱存取" aria-label="Permalink to &quot;投递链与邮箱存取&quot;">​</a></h3><p>SMTP 跳到跳，IMAP 状态在服务器。逐跳 TLS 不是端到端密信。网页邮箱不是协议。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：MUA → 提交 → MTA 链 → 投递 → IMAP 取。对照 HTTP POST：无统一缓存，有队列与重试。与 QUIC：邮件仍多 TCP。</p><p><span class="marginnote">数字实例：端口各记一个——客户端发信走 587（submission，通常要求登录并 STARTTLS），服务器之间走 25（中继，公网可达），IMAP 是 143（明文后升级）或 993（TLS 直连）。配邮件客户端时端口选错，症状多半是「连得上但发不出去」，而不是直接连不上。</span></p>',13)),(E(),T(i,null,{default:A(()=>[B(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20MUA%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%20--%3E%20SUB%5B%22SMTP%20%E6%8F%90%E4%BA%A4%22%5D%0A%20%20SUB%20--%3E%20MTA%5B%22MTA%20%E5%88%B0%20MTA%22%5D%0A%20%20MTA%20--%3E%20STORE%5B%22%E9%82%AE%E7%AE%B1%E5%AD%98%E5%82%A8%22%5D%0A%20%20STORE%20--%3E%20IMAP%5B%22IMAP%20%E5%AD%98%E5%8F%96%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[e("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"DNS 缓存 MX 影响切换。TLS 对 SMTP 是逐跳，不是端到端密信（那是 OpenPGP/S/MIME，点名）。负载均衡对 25 端口要小心会话。分块附件像 HTTP 体，但边界是 MIME。",-1)),(E(),T(i,null,{default:A(()=>[B(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E8%BF%9E%E4%B8%8A%E6%8F%90%E4%BA%A4%E6%88%96%E4%B8%AD%E7%BB%A7%E7%AB%AF%E5%8F%A3%22%5D%20--%3E%20EH%5B%22EHLO%20%E9%97%AE%E5%80%99%20%E5%8D%8F%E5%95%86%E8%83%BD%E5%8A%9B%22%5D%0A%20%20EH%20--%3E%20MF%5B%22MAIL%20FROM%20%E5%A3%B0%E6%98%8E%E5%8F%91%E4%BB%B6%E4%BA%BA%22%5D%0A%20%20MF%20--%3E%20RT%5B%22RCPT%20TO%20%E9%80%90%E4%B8%AA%E7%BB%99%E6%94%B6%E4%BB%B6%E4%BA%BA%22%5D%0A%20%20RT%20--%3E%20DA%5B%22DATA%20%E4%BC%A0%E6%AD%A3%E6%96%87%20%E4%BB%A5%E5%8D%95%E7%8B%AC%E4%B8%80%E8%A1%8C%E7%82%B9%E5%8F%B7%E7%BB%93%E6%9D%9F%22%5D%0A%20%20DA%20--%3E%20Q%7B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E6%8E%A5%E5%8F%97%E5%90%97%3F%22%7D%0A%20%20Q%20--%20%22%E6%8E%A5%E5%8F%97%20250%22%20--%3E%20MO%5B%22%E5%85%A5%E9%98%9F%20%E7%BB%A7%E7%BB%AD%E4%B8%8B%E4%B8%80%E8%B7%B3%22%5D%0A%20%20Q%20--%20%22%E6%8B%92%E7%BB%9D%204xx%2F5xx%22%20--%3E%20RP%5B%224xx%20%E5%BB%B6%E8%BF%9F%E9%87%8D%E8%AF%95%EF%BC%8C5xx%20%E9%80%80%E4%BF%A1%22%5D%0A%20%20MO%20--%3E%20QU%5B%22QUIT%20%E7%BB%93%E6%9D%9F%E4%BC%9A%E8%AF%9D%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">常见误区：以为逐跳 TLS 等于端到端加密。每段 TLS 只保护「这一段链路」，中途每个 MTA 都看得见、也改得了明文；真正的内容保密要靠 OpenPGP 或 S/MIME 在信体上另加一层——MTA 只剩信封，看不见信纸。</span></p><p>垃圾与伪造下一课认证。保活防止 NAT 拆 IMAP。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 JMAP 的全部。SPF/DKIM/DMARC 是下一课。后课默认：SMTP 推送投递；IMAP 远程邮箱。</p><p>把 25 对全世界开放中继会成为垃圾跳板。</p><p>下一课<a href="/cs/spf-dkim-dmarc">SPF / DKIM / DMARC</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SMTP 管投递链；IMAP 管邮箱访问。</li><li>MX 与逐跳 TLS 是核心机制。</li><li>与 HTTP 会话模型不同。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 5321；RFC 9051。</li></ul>',8))])}const c=l(o,[["render",p]]);export{h as __pageData,c as default};
